import React, { useState } from "react";
import { ColorModeProvider } from "../../lib/styling";
import Inline from "../Inline";
import Toggle from "./";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Toggle> = {
  title: "Components/Toggle",
  component: Toggle,
  args: {
    label: "Label",
    disabled: false,
  },
  argTypes: {
    checked: {
      type: "boolean",
      description: "Controls whether the Toggle is checked",
    },
    disabled: {
      type: "boolean",
      description: "Controls whether the toggle is disabled",
    },
    size: {
      options: ["small", "medium", "large"],
      control: "radio",
      description: "The size of the toggle",
    },
  },
};
export default meta;
type Story = StoryObj<typeof Toggle>;

export const Default: Story = {
  render: (args) => {
    return <Toggle {...args} />;
  },
};
export const Basic: Story = {
  tags: ["visual-test"],
  render: () => {
    return (
      <Inline spacing="2-x">
        <Toggle label="Label" defaultChecked />
        <Toggle label="Label" />
      </Inline>
    );
  },
};

export const Disabled: Story = {
  render: () => {
    return (
      <Inline spacing="2-x">
        <Toggle label="Label" defaultChecked disabled />
        <Toggle label="Label" disabled />
      </Inline>
    );
  },
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => {
    return (
      <Inline spacing="2-x">
        <Toggle label="Label" defaultChecked />
        <Toggle label="Label" />
      </Inline>
    );
  },
};

export const Size: Story = {
  render: () => {
    return (
      <Inline spacing="2-x">
        <Toggle label="Large" size="large" defaultChecked />
        <Toggle label="Medium" defaultChecked />
        <Toggle label="Small" size="small" defaultChecked />
      </Inline>
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [options, setOptions] = useState({ option1: true, option2: false });
    // Note: for react16 or earlier you need to persist event properties
    // See https://legacy.reactjs.org/docs/legacy-event-pooling.html
    return (
      <Inline spacing="2-x">
        <Toggle
          label="Option 1"
          checked={options.option1}
          onChange={(event) => {
            const checkedValue = event.target.checked;
            setOptions((prevState) => ({
              ...prevState,
              option1: checkedValue,
            }));
          }}
        />
        <Toggle
          label="Option 2"
          checked={options.option2}
          onChange={(event) => {
            const checkedValue = event.target.checked;
            setOptions((prevState) => ({
              ...prevState,
              option2: checkedValue,
            }));
          }}
        />
      </Inline>
    );
  },
};
